func testRotinaContabilToManyAddOpRocAdiantamentoEntidades(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a RotinaContabil
	var b, c, d, e AdiantamentoEntidade

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, rotinaContabilDBTypes, false, strmangle.SetComplement(rotinaContabilPrimaryKeyColumns, rotinaContabilColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*AdiantamentoEntidade{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, adiantamentoEntidadeDBTypes, false, strmangle.SetComplement(adiantamentoEntidadePrimaryKeyColumns, adiantamentoEntidadeColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*AdiantamentoEntidade{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddRocAdiantamentoEntidades(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if !queries.Equal(a.RocID, first.RocID) {
			t.Error("foreign key was wrong value", a.RocID, first.RocID)
		}
		if !queries.Equal(a.RocID, second.RocID) {
			t.Error("foreign key was wrong value", a.RocID, second.RocID)
		}

		if first.R.Roc != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Roc != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.RocAdiantamentoEntidades[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.RocAdiantamentoEntidades[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.RocAdiantamentoEntidades().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

func testRotinaContabilToManySetOpRocAdiantamentoEntidades(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a RotinaContabil
	var b, c, d, e AdiantamentoEntidade

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, rotinaContabilDBTypes, false, strmangle.SetComplement(rotinaContabilPrimaryKeyColumns, rotinaContabilColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*AdiantamentoEntidade{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, adiantamentoEntidadeDBTypes, false, strmangle.SetComplement(adiantamentoEntidadePrimaryKeyColumns, adiantamentoEntidadeColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err = a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.SetRocAdiantamentoEntidades(ctx, tx, false, &b, &c)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.RocAdiantamentoEntidades().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	err = a.SetRocAdiantamentoEntidades(ctx, tx, true, &d, &e)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.RocAdiantamentoEntidades().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.RocID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.RocID) {
		t.Error("want c's foreign key value to be nil")
	}
	if !queries.Equal(a.RocID, d.RocID) {
		t.Error("foreign key was wrong value", a.RocID, d.RocID)
	}
	if !queries.Equal(a.RocID, e.RocID) {
		t.Error("foreign key was wrong value", a.RocID, e.RocID)
	}

	if b.R.Roc != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Roc != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Roc != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}
	if e.R.Roc != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}

	if a.R.RocAdiantamentoEntidades[0] != &d {
		t.Error("relationship struct slice not set to correct value")
	}
	if a.R.RocAdiantamentoEntidades[1] != &e {
		t.Error("relationship struct slice not set to correct value")
	}
}

func testRotinaContabilToManyRemoveOpRocAdiantamentoEntidades(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a RotinaContabil
	var b, c, d, e AdiantamentoEntidade

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, rotinaContabilDBTypes, false, strmangle.SetComplement(rotinaContabilPrimaryKeyColumns, rotinaContabilColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*AdiantamentoEntidade{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, adiantamentoEntidadeDBTypes, false, strmangle.SetComplement(adiantamentoEntidadePrimaryKeyColumns, adiantamentoEntidadeColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddRocAdiantamentoEntidades(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.RocAdiantamentoEntidades().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveRocAdiantamentoEntidades(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.RocAdiantamentoEntidades().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.RocID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.RocID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Roc != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Roc != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Roc != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Roc != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.RocAdiantamentoEntidades) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.RocAdiantamentoEntidades[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.RocAdiantamentoEntidades[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

